  ensures (result == (sum i in 0..len(xs): count j in (i + 1)..len(xs): ((xs[i] + xs[j]) == t)))
  effects pure
  example (count_pairs_sum([1, 2, 3, 4], 5) == 2)
  example (count_pairs_sum([1, 2], 9) == 0)
  example (count_pairs_sum([1, 4, 6, 9], 10) == 2)
  example (count_pairs_sum([], 0) == 0)
{
  match xs { [] => 0 [h, ..r] => (hits(r, (t - h)) + count_pairs_sum(r, xs)) }
}

fn hits(xs: List[Int], v: Int) -> Int
  requires distinct(xs)
  ensures (result == count(xs, v))
  effects pure
  example (hits([1, 2, 3], 2) == 1)
  example (hits([], 5) == 0)
{
  match xs { [] => 0 [h, ..r] => if (h == v) then (1 + hits(r, v)) else hits(r, v) }
}

